package com.digitalbase.ticketing.service;import com.digitalbase.ticketing.dto.*;import com.digitalbase.ticketing.enums.NotificationType;import com.digitalbase.ticketing.enums.ProductStatus;import com.digitalbase.ticketing.enums.Role;import com.digitalbase.ticketing.enums.TicketStatus;import com.digitalbase.ticketing.exception.DuplicateResourceException; // 👈 အသစ် Import လုပ်ထားပါသည်import com.digitalbase.ticketing.exception.InvalidTicketStateException;import com.digitalbase.ticketing.exception.ResourceNotFoundException;import com.digitalbase.ticketing.exception.TicketAccessDeniedException;import com.digitalbase.ticketing.model.*;import com.digitalbase.ticketing.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.Page;import org.springframework.data.domain.PageRequest;import org.springframework.data.domain.Pageable;import org.springframework.data.domain.Sort;import org.springframework.data.jpa.domain.Specification;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.time.LocalDate;import java.time.ZoneId;import java.util.List;import java.util.Optional;import java.util.stream.Collectors;@Service@RequiredArgsConstructorpublic class ClientProductServiceImpl implements ClientProductService {    private final ClientProductRepository clientProductRepository;    private final TicketRepository ticketRepository;    private final UserRepository userRepository;    private final ProductRepository productRepository;    private final ProductPlanRepository productPlanRepository;    private final NotificationSseService notificationSseService;    @Override    @Transactional    public ClientProductResponse assignProductToClient(ClientProductRequest request) {        User user = userRepository.findById(request.getUserId())                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        Product product = productRepository.findById(request.getProductId())                .orElseThrow(() -> new ResourceNotFoundException("Product not found"));        // 💡 [အပြောင်းအလဲ - ၁] Request က ပို့လိုက်တဲ့ planId ဖြင့် ProductPlan Entity ကို ရှာပါမည်        ProductPlan productPlan = productPlanRepository.findById(request.getPlanId())                .orElseThrow(() -> new ResourceNotFoundException("Product plan not found"));        Instant now = Instant.now();        Instant newStartDate = now;        // 💡 [အပြောင်းအလဲ - ၂] Frontend မှ Duration / Minutes မပို့ပါက Database ထဲရှိ Plan ရဲ့တန်ဖိုးကို အလိုအလျောက် ယူပါမည်        long planDurationDays = request.getDurationDays() != null ? request.getDurationDays() : productPlan.getDurationDays();        int totalMinutes = request.getTotalMinutes() != null ? request.getTotalMinutes() : productPlan.getTotalMinutes();        // 🧠 [Business Logic] အရင် Plan အဟောင်း ရှိ/မရှိ နှင့် သက်တမ်းကုန်/မကုန် စစ်ဆေးခြင်း        Optional<ClientProduct> latestPlan = clientProductRepository.findTopByUserIdAndProductIdOrderByPlanEndDateDesc(user.getId(), product.getId());        if (latestPlan.isPresent()) {            Instant lastEndDate = latestPlan.get().getPlanEndDate();            // ယခင် Plan သည် သက်တမ်းမကုန်သေးပါက (Active ဖြစ်နေပါက)            if (lastEndDate != null && lastEndDate.isAfter(now)) {                newStartDate = lastEndDate; // အသစ်၏ Start Date ကို အဟောင်းကုန်မည့်ရက်မှ စတင်မည်            }        }        // 📅 အသစ်၏ End Date ကို တွက်ချက်ခြင်း        Instant newEndDate = newStartDate.plus(planDurationDays, java.time.temporal.ChronoUnit.DAYS);        ClientProduct clientProduct = ClientProduct.builder()                .user(user)                .product(product)                .productPlan(productPlan)                .purchasedDate(now)                .planStartDate(newStartDate)                .planEndDate(newEndDate)                .totalMinutes(totalMinutes)      // 👈 ပြင်ဆင်ထားသော variable ကို သုံးပါ                .availableMinutes(totalMinutes)  // 👈 ပြင်ဆင်ထားသော variable ကို သုံးပါ                .build();        clientProduct.setStatus(getDynamicStatus(clientProduct));        ClientProduct savedClientProduct = clientProductRepository.save(clientProduct);        return mapToResponse(savedClientProduct);    }    @Override    @Transactional    public ClientProductResponse renewProductPlan(ClientProductRequest request) {        User user = userRepository.findById(request.getUserId())                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        Product product = productRepository.findById(request.getProductId())                .orElseThrow(() -> new ResourceNotFoundException("Product not found"));        // 💡 [အပြောင်းအလဲ - ၁] Request က ပို့လိုက်တဲ့ planId ဖြင့် ProductPlan Entity ကို အရင်ရှာပါမည်        ProductPlan productPlan = productPlanRepository.findById(request.getPlanId())                .orElseThrow(() -> new ResourceNotFoundException("Product plan not found"));        Instant now = Instant.now();        Instant newStartDate = now;        // 💡 [အပြောင်းအလဲ - ၂] Frontend မှ ရက် သို့မဟုတ် မိနစ် မပို့ပါက Database ထဲရှိ Plan ရဲ့တန်ဖိုးကို အလိုအလျောက် ယူပါမည်        long planDurationDays = request.getDurationDays() != null ? request.getDurationDays() : productPlan.getDurationDays();        int totalMinutes = request.getTotalMinutes() != null ? request.getTotalMinutes() : productPlan.getTotalMinutes();        // 🔍 Database ထဲမှ ဤ Customer ၏ နောက်ဆုံးဝယ်ထားသော Plan ကို ရှာဖွေခြင်း        Optional<ClientProduct> latestPlan = clientProductRepository.findTopByUserIdAndProductIdOrderByPlanEndDateDesc(user.getId(), product.getId());        if (latestPlan.isPresent()) {            Instant lastEndDate = latestPlan.get().getPlanEndDate();            // 💡 ယခင် Plan သည် သက်တမ်းမကုန်သေးပါက၊ ထိုရက်စွဲကို Start Date အသစ်အဖြစ် သတ်မှတ်မည်            if (lastEndDate != null && lastEndDate.isAfter(now)) {                newStartDate = lastEndDate;            }        }        // 📅 အသစ်ဝယ်လိုက်သော သက်တမ်း (ရက်အရေအတွက်) ကို Start Date အသစ်ပေါ်တွင် ပေါင်းထည့်မည်        Instant newEndDate = newStartDate.plus(planDurationDays, java.time.temporal.ChronoUnit.DAYS);        ClientProduct renewedPlan = ClientProduct.builder()                .user(user)                .product(product)                .productPlan(productPlan)                .purchasedDate(now)                .planStartDate(newStartDate)                .planEndDate(newEndDate)                .totalMinutes(totalMinutes)      // 👈 ပြင်ဆင်ထားသော variable ကို သုံးပါ                .availableMinutes(totalMinutes)  // 👈 ပြင်ဆင်ထားသော variable ကို သုံးပါ                .build();        renewedPlan.setStatus(getDynamicStatus(renewedPlan));        ClientProduct savedPlan = clientProductRepository.save(renewedPlan);        return mapToResponse(savedPlan);    }    @Override    @Transactional    public AddExtraHoursResponse addExtraHours(Long clientProductId, AddExtraHoursRequest request, String adminEmail) {        User admin = userRepository.findByEmail(adminEmail)                .orElseThrow(() -> new ResourceNotFoundException("Admin not found"));        if (admin.getRole() != Role.ADMIN && admin.getRole() != Role.SERVICE_ADMIN) {            throw new TicketAccessDeniedException("Only Admin or Service Admin can add extra SLA hours.");        }        ClientProduct cp = clientProductRepository.findById(clientProductId)                .orElseThrow(() -> new ResourceNotFoundException("Client Product not found with ID: " + clientProductId));        // ၁။ EXPIRED သို့မဟုတ် DISABLED Plan ဖြစ်နေလျှင် Extra Hours မထည့်ပေးပါ        ZoneId yangonZone = ZoneId.of("Asia/Yangon");        LocalDate today = LocalDate.now(yangonZone);        boolean isDateExpired = cp.getPlanEndDate() != null                && cp.getPlanEndDate().atZone(yangonZone).toLocalDate().isBefore(today);        if (cp.getStatus() == ProductStatus.EXPIRED || cp.getStatus() == ProductStatus.DISABLED || isDateExpired) {            throw new InvalidTicketStateException("Cannot add extra hours to an expired or disabled plan.");        }        // ၂။ Hours ကို Minutes သို့ ပြောင်းလဲတွက်ချက်ခြင်း        int addedMinutes = (int) Math.round(request.getExtraHours() * 60);        if (addedMinutes <= 0) {            throw new IllegalArgumentException("Added minutes must be greater than 0.");        }        int currentExtra = cp.getExtraMinutes() != null ? cp.getExtraMinutes() : 0;        int currentAvailable = cp.getAvailableMinutes() != null ? cp.getAvailableMinutes() : 0;        cp.setExtraMinutes(currentExtra + addedMinutes);        cp.setAvailableMinutes(currentAvailable + addedMinutes);        // NO_HOURS_LEFT status enum သီးသန့်သုံးထားပါက ACTIVE ပြန်ပြောင်းပေးနိုင်သည်        if (cp.getStatus() == ProductStatus.UPCOMING) {            // UPCOMING ပေါ်တွင် ထည့်ခြင်းဖြစ်ပါက status မပြောင်းဘဲ မိနစ်သာ ပေါင်းထားမည်        }        ClientProduct savedCp = clientProductRepository.save(cp);        String productName = (savedCp.getProduct() != null && savedCp.getProduct().getName() != null)                ? savedCp.getProduct().getName()                : "your product";        String planName = (savedCp.getProductPlan() != null && savedCp.getProductPlan().getPlanName() != null)                ? savedCp.getProductPlan().getPlanName()                : "Custom Plan";        // ၃။ Client ထံ Notification ပို့ခြင်း        if (savedCp.getUser() != null) {            String notiMsg = String.format(                    "%.1f extra SLA hour(s) (%d mins) have been added to your %s (%s). New available balance: %d mins.",                    request.getExtraHours(), addedMinutes, productName, planName, savedCp.getAvailableMinutes()            );            if (request.getReason() != null && !request.getReason().trim().isEmpty()) {                notiMsg += " Note: " + request.getReason().trim();            }            Notification noti = Notification.builder()                    .user(savedCp.getUser())                    .type(NotificationType.SLA_ALERT)                    .title("Extra SLA Hours Added")                    .message(notiMsg)                    .actionText("View Plan")                    .actionUrl("/my-products/" + savedCp.getId())                    .isRead(false)                    .build();            notificationSseService.sendNotification(savedCp.getUser().getEmail(), noti);        }        return AddExtraHoursResponse.builder()                .clientProductId(savedCp.getId())                .productName(productName)                .planName(planName)                .addedMinutes(addedMinutes)                .totalPlanMinutes(savedCp.getTotalMinutes())                .totalExtraMinutes(savedCp.getExtraMinutes())                .newAvailableMinutes(savedCp.getAvailableMinutes())                .message("Successfully added " + addedMinutes + " extra minutes.")                .build();    }    @Override    @Transactional(readOnly = true)    public DashboardSummaryResponse getDashboardSummary(String email, Long productId) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        List<ClientProduct> products;        if (productId != null) {            products = clientProductRepository.findAllByUserIdAndProductId(user.getId(), productId);        } else {            products = clientProductRepository.findAllByUserId(user.getId());        }        if (products.isEmpty()) {            return DashboardSummaryResponse.builder().build();        }        ZoneId yangonZone = ZoneId.of("Asia/Yangon");        LocalDate today = LocalDate.now(yangonZone);        int activeTotalMins = 0;        int activeAvailableMins = 0;        int activeUsedMins = 0;        int activeExtraUsedMins = 0;        ClientProduct activeProduct = null;        for (ClientProduct cp : products) {            ProductStatus dynamicStatus = getDynamicStatus(cp);            if (dynamicStatus == ProductStatus.ACTIVE || dynamicStatus == ProductStatus.EXPIRING_SOON) {                int baseMins = cp.getTotalMinutes() != null ? cp.getTotalMinutes() : 0;                int topUpMins = cp.getExtraMinutes() != null ? cp.getExtraMinutes() : 0;                int overageMins = cp.getOverageMinutes() != null ? cp.getOverageMinutes() : 0;                int availMins = cp.getAvailableMinutes() != null ? cp.getAvailableMinutes() : 0;                // 🎯 Base Plan + Admin Top-up (Total Pool)                int poolMins = baseMins + topUpMins;                // 🎯 Pool ထဲမှ သုံးပြီးသား + Plan ကျော်လွန် Overage                int usedOnPlan = Math.max(0, poolMins - availMins) + overageMins;                activeTotalMins += poolMins;                activeAvailableMins += Math.max(0, availMins);                activeUsedMins += usedOnPlan;                // 🎯 မူလ Plan ထက် ကျော်လွန်သုံးစွဲထားသော Extra Minutes (Top-up သုံးပြီးသား + Overage + Legacy Negative)                activeExtraUsedMins += Math.max(0, usedOnPlan - baseMins);                // 🎯 Active Plan ရွေးချယ်ရာတွင် မိနစ်ကျန်သေးသော Plan ကို ဦးစားပေးပြီး၊ တူနေပါက အစောဆုံးကုန်မည့် Plan ကို ယူမည်                if (activeProduct == null) {                    activeProduct = cp;                } else {                    boolean currentHasHours = availMins > 0;                    boolean selectedHasHours = activeProduct.getAvailableMinutes() != null && activeProduct.getAvailableMinutes() > 0;                    if (currentHasHours && !selectedHasHours) {                        activeProduct = cp;                    } else if (currentHasHours == selectedHasHours                            && cp.getPlanEndDate() != null                            && activeProduct.getPlanEndDate() != null                            && cp.getPlanEndDate().isBefore(activeProduct.getPlanEndDate())) {                        activeProduct = cp;                    }                }            }        }        // 📅 ရက်စွဲနှင့် Expiry စာသားများ တွက်ချက်ခြင်း (Asia/Yangon Timezone)        long daysRemaining = 0;        String expiryString = "N/A";        String planStartDate = "N/A";        String planEndDate = "N/A";        if (activeProduct != null && activeProduct.getPlanEndDate() != null) {            LocalDate endDateLocal = activeProduct.getPlanEndDate().atZone(yangonZone).toLocalDate();            daysRemaining = Math.max(0, java.time.temporal.ChronoUnit.DAYS.between(today, endDateLocal));            java.time.format.DateTimeFormatter expFormatter =                    java.time.format.DateTimeFormatter.ofPattern("'Expired in' MMM d").withZone(yangonZone);            expiryString = expFormatter.format(activeProduct.getPlanEndDate());            java.time.format.DateTimeFormatter rangeFormatter =                    java.time.format.DateTimeFormatter.ofPattern("dd.MM.yyyy").withZone(yangonZone);            if (activeProduct.getPlanStartDate() != null) {                planStartDate = rangeFormatter.format(activeProduct.getPlanStartDate());            }            planEndDate = rangeFormatter.format(activeProduct.getPlanEndDate());        }        Instant startOfToday = today.atStartOfDay(yangonZone).toInstant();        List<Long> cpIds = products.stream().map(ClientProduct::getId).collect(Collectors.toList());        long totalSubmitted = 0, todaySubmitted = 0;        long totalResolved = 0, todayResolved = 0;        long totalReopened = 0, todayReopened = 0;        if (!cpIds.isEmpty()) {            List<TicketStatus> submittedList = List.of(TicketStatus.SUBMITTED);            totalSubmitted = ticketRepository.countByClientProductIdInAndStatusIn(cpIds, submittedList);            todaySubmitted = ticketRepository.countByClientProductIdInAndStatusInAndCreatedAtAfter(cpIds, submittedList, startOfToday);            List<TicketStatus> resolvedList = List.of(TicketStatus.RESOLVED, TicketStatus.CLOSED);            totalResolved = ticketRepository.countByClientProductIdInAndStatusIn(cpIds, resolvedList);            todayResolved = ticketRepository.countByClientProductIdInAndStatusInAndUpdatedAtAfter(cpIds, resolvedList, startOfToday);            List<TicketStatus> reopenedList = List.of(TicketStatus.REOPENED);            totalReopened = ticketRepository.countByClientProductIdInAndStatusIn(cpIds, reopenedList);            todayReopened = ticketRepository.countByClientProductIdInAndStatusInAndUpdatedAtAfter(cpIds, reopenedList, startOfToday);        }        return DashboardSummaryResponse.builder()                .slaHoursCard(DashboardSummaryResponse.SlaHoursCard.builder()                        .remainingMinutes(activeAvailableMins)                        .totalMinutes(activeTotalMins)                        .expiryDateText(expiryString)                        .daysRemaining((int) daysRemaining)                        .build())                .submittedTicketsCard(DashboardSummaryResponse.TicketStatCard.builder().totalCount((int) totalSubmitted).todayCount((int) todaySubmitted).build())                .resolvedTicketsCard(DashboardSummaryResponse.TicketStatCard.builder().totalCount((int) totalResolved).todayCount((int) todayResolved).build())                .reopenedTicketsCard(DashboardSummaryResponse.TicketStatCard.builder().totalCount((int) totalReopened).todayCount((int) todayReopened).build())                .planName(activeProduct != null && activeProduct.getProductPlan() != null ? activeProduct.getProductPlan().getPlanName() : "No Active Plan")                .planStartDate(planStartDate)                .planEndDate(planEndDate)                .status(activeProduct != null ? getDynamicStatus(activeProduct).name() : "DISABLED")                // ⏱️ မိနစ်များသာ (Integers) ပြန်ပို့မည်                .purchasedMinutes(activeTotalMins)                .usedMinutes(activeUsedMins)                .availableMinutes(activeAvailableMins)                .extraMinutes(activeExtraUsedMins)                .build();    }    @Override    public MyProductDashboardResponse getMyProducts(String email) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        List<ClientProduct> clientProducts = clientProductRepository.findAllByUserId(user.getId());        // 💡 [Fix 1] Unique ဖြစ်သော Product အမည် အရေအတွက် ကိုသာ ရေတွက်မည်        int totalUniqueProducts = (int) clientProducts.stream()                .map(cp -> cp.getProduct().getId())                .distinct()                .count();        // 💡 [Fix 2] Unique ဖြစ်သော Active Product အရေအတွက်ကိုသာ ရေတွက်မည်        int activeProducts = (int) clientProducts.stream()                .filter(cp -> {                    ProductStatus status = getDynamicStatus(cp);                    return status == ProductStatus.ACTIVE || status == ProductStatus.EXPIRING_SOON;                })                .map(cp -> cp.getProduct().getId())                .distinct()                .count();        // 🟢 [Fix 3] ACTIVE နှင့် EXPIRING_SOON ဖြစ်သော Plan များ၏ 'ကျန်ရှိသော' မိနစ်များကိုသာ ပေါင်းမည် (Minutes အတိုင်းထားမည်)        int totalSlaMinutes = clientProducts.stream()                .filter(cp -> {                    ProductStatus status = getDynamicStatus(cp);                    return status == ProductStatus.ACTIVE || status == ProductStatus.EXPIRING_SOON;                })                .mapToInt(ClientProduct::getAvailableMinutes)                .sum(); // 👈 / 60 ကို ဖြုတ်လိုက်ပါပြီ        // 🔵 [Fix 4] UPCOMING ဖြစ်သော Plan များ၏ မိနစ်များကို သီးသန့် ပေါင်းမည် (Minutes အတိုင်းထားမည်)        int upcomingSlaMinutes = clientProducts.stream()                .filter(cp -> getDynamicStatus(cp) == ProductStatus.UPCOMING)                .mapToInt(ClientProduct::getAvailableMinutes)                .sum(); // 👈 / 60 ကို ဖြုတ်လိုက်ပါပြီ        // 🔴 ကျော်လွန်သုံးစွဲထားသော မိနစ်များ (Minutes အတိုင်းထားမည်)        int extraUsageMinutes = clientProducts.stream()                .filter(cp -> cp.getAvailableMinutes() < 0)                .mapToInt(cp -> Math.abs(cp.getAvailableMinutes()))                .sum(); // 👈 / 60 ကို ဖြုတ်လိုက်ပါပြီ        // 🎯 [Fix 5] Product ID တူနေပါက အရေးကြီးဆုံး Status ကိုသာ ရွေးချယ်ပြီး Duplicate မဖြစ်အောင် စစ်ထုတ်မည်        List<ClientProductResponse> productResponses = clientProducts.stream()                .collect(Collectors.toMap(                        cp -> cp.getProduct().getId(), // Key: Product ID                        cp -> cp,                      // Value: ClientProduct                        (existing, replacement) -> {   // Product ထပ်နေလျှင် Status ရွေးချယ်ခြင်း                            ProductStatus s1 = getDynamicStatus(existing);                            ProductStatus s2 = getDynamicStatus(replacement);                            // ACTIVE သို့မဟုတ် EXPIRING_SOON ကို အမြင့်ဆုံး ဦးစားပေးမည်                            if (s1 == ProductStatus.ACTIVE || s1 == ProductStatus.EXPIRING_SOON) return existing;                            if (s2 == ProductStatus.ACTIVE || s2 == ProductStatus.EXPIRING_SOON) return replacement;                            // ထိုနှစ်ခုမရှိလျှင် UPCOMING ကို ဒုတိယဦးစားပေးမည်                            if (s1 == ProductStatus.UPCOMING) return existing;                            return replacement;                        }                ))                .values()                .stream()                .map(this::mapToResponse)                .collect(Collectors.toList());        return MyProductDashboardResponse.builder()                .totalProducts(totalUniqueProducts)                .totalSlaMinutes(totalSlaMinutes)       // 👈 Minutes သို့ နာမည်ပြောင်းထားသည်                .upcomingSlaMinutes(upcomingSlaMinutes) // 👈 Minutes သို့ နာမည်ပြောင်းထားသည်                .activeProducts(activeProducts)                .extraUsageMinutes(extraUsageMinutes)   // 👈 Minutes သို့ နာမည်ပြောင်းထားသည်                .products(productResponses)             // 👈 Duplicate စစ်ထုတ်ထားသော List                .build();    }    @Override    public ClientProductDetailResponse getProductDetailsByProductId(Long productId, String email) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        // 💡 Join Table မလိုပါ။ User ID နှင့် Product ID တူသော Plan အားလုံးကို ဆွဲထုတ်လိုက်ခြင်း ဖြစ်ပါသည်။        List<ClientProduct> allPlans = clientProductRepository.findAllByUserIdAndProductId(user.getId(), productId);        if (allPlans.isEmpty()) {            throw new ResourceNotFoundException("No SLA plans found for this product.");        }        // Product အချက်အလက်များကို ပထမဆုံး Plan မှ ဆွဲယူပါမည် (မည်သည့် Plan မှ ယူယူ အတူတူပင်ဖြစ်သည်)        Product product = allPlans.get(0).getProduct();        // 🟢 Current Plan (ACTIVE သို့မဟုတ် EXPIRING_SOON ကို ရှာခြင်း)        SlaPlanInfo currentPlan = allPlans.stream()                .filter(cp -> getDynamicStatus(cp) == ProductStatus.ACTIVE || getDynamicStatus(cp) == ProductStatus.EXPIRING_SOON)                .findFirst()                .map(this::mapToSlaPlanInfo)                .orElse(null);        // 🔵 Upcoming Plans (UPCOMING အားလုံးကို ရှာခြင်း)        List<SlaPlanInfo> upcomingPlans = allPlans.stream()                .filter(cp -> getDynamicStatus(cp) == ProductStatus.UPCOMING)                .map(this::mapToSlaPlanInfo)                .collect(Collectors.toList());        // ⚪ Past Plans (EXPIRED အားလုံးကို ရှာခြင်း)        List<SlaPlanInfo> pastPlans = allPlans.stream()                .filter(cp -> getDynamicStatus(cp) == ProductStatus.EXPIRED)                .map(this::mapToSlaPlanInfo)                .collect(Collectors.toList());        return ClientProductDetailResponse.builder()                .productId(product.getId())                .productName(product.getName())                .productDescription(product.getDescription())                .productType(product.getProductType())                .imageUrl(product.getImageUrl())                .currentPlan(currentPlan)                .upcomingPlans(upcomingPlans)                .pastPlans(pastPlans)                .build();    }    // Helper Method (မိနစ်များ တွက်ချက်ခြင်း)    private SlaPlanInfo mapToSlaPlanInfo(ClientProduct cp) {        int availMins = cp.getAvailableMinutes() != null ? cp.getAvailableMinutes() : 0;        int totalMins = cp.getTotalMinutes() != null ? cp.getTotalMinutes() : 0;        int remainMinsTotal = Math.max(availMins, 0);        int extraMinsTotal = availMins < 0 ? Math.abs(availMins) : 0;        int usedMinsTotal = availMins >= 0 ? totalMins - availMins : totalMins;        long daysRemaining = 0;        if (cp.getPlanEndDate() != null) {            daysRemaining = java.time.temporal.ChronoUnit.DAYS.between(java.time.Instant.now(), cp.getPlanEndDate());            if(daysRemaining < 0) daysRemaining = 0;        }        return SlaPlanInfo.builder()                .clientProductId(cp.getId())                // 💡 [ပြောင်းလဲချက်] cp.getSupportPlan() အစား cp.getProductPlan().getPlanName() ကို အသုံးပြုထားပါသည်                .supportPlan(cp.getProductPlan().getPlanName())                .status(getDynamicStatus(cp).name())                .purchasedDate(cp.getPurchasedDate() != null ? cp.getPurchasedDate().toString() : null)                .planStartDate(cp.getPlanStartDate() != null ? cp.getPlanStartDate().toString() : null)                .planEndDate(cp.getPlanEndDate() != null ? cp.getPlanEndDate().toString() : null)                .totalMinutes(totalMins)                .remainingMinutes(remainMinsTotal)                .usedMinutes(usedMinsTotal)                .extraMinutes(extraMinsTotal)                .daysRemaining(daysRemaining)                .build();    }    @Override    public Page<ProductTicketDto> getProductRelatedTickets(            Long productId, String email,            String statusFilter, String startDateStr, String endDateStr,            int page, int size) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        // 🎯 User ၏ ClientProduct များထဲမှ လက်ရှိ productId နှင့် သက်ဆိုင်သော ID အားလုံးကို ရှာထုတ်ခြင်း        List<Long> matchedClientProductIds = clientProductRepository.findAllByUserId(user.getId())                .stream()                .filter(cp -> cp.getProduct().getId().equals(productId))                .map(ClientProduct::getId)                .collect(Collectors.toList());        Pageable pageable = PageRequest.of(page, size, Sort.by("createdAt").descending());        // 🎯 ID လုံးဝ မရှိလျှင် စောစီးစွာ Return ပြန်ခြင်း (Early Return)        if (matchedClientProductIds.isEmpty()) {            if (!user.getRole().name().equals("ADMIN")) {                throw new ResourceNotFoundException("Product not found or access denied");            } else {                return Page.empty(pageable); // Admin ဖြစ်လျှင် Ticket အလွတ်သာ ပြမည်            }        }        // Filter များကို ပြင်ဆင်ခြင်း        TicketStatus status = null;        if (statusFilter != null && !statusFilter.isEmpty() && !statusFilter.equalsIgnoreCase("ALL")) {            try {                status = TicketStatus.valueOf(statusFilter.toUpperCase());            } catch (IllegalArgumentException e) { /* Ignore */ }        }        Instant startDate = null;        Instant endDate = null;        try {            if (startDateStr != null && !startDateStr.isEmpty()) {                startDate = Instant.parse(startDateStr);            }            if (endDateStr != null && !endDateStr.isEmpty()) {                endDate = Instant.parse(endDateStr);            }        } catch (Exception e) { /* Ignore */ }        // =========================================================================        // 🎯 [အပြောင်းအလဲ] null ဖြင့် မစတော့ဘဲ မဖြစ်မနေပါရမည့် IN Query ဖြင့် တိုက်ရိုက်စတင်ခြင်း        // =========================================================================        Specification<Ticket> spec = Specification.where((root, query, cb) ->                root.get("clientProduct").get("id").in(matchedClientProductIds)        );        if (status != null) {            spec = spec.and(TicketSpecification.hasStatus(status));        }        if (startDate != null) {            spec = spec.and(TicketSpecification.createdAfter(startDate));        }        if (endDate != null) {            spec = spec.and(TicketSpecification.createdBefore(endDate));        }        Page<Ticket> tickets = ticketRepository.findAll(spec, pageable);        return tickets.map(t -> {            String assignedNames = "Pending";            if (t.getAssignments() != null && !t.getAssignments().isEmpty()) {                assignedNames = t.getAssignments().stream()                        .map(a -> a.getDeveloper().getFullName())                        .collect(Collectors.joining(", "));            }            return ProductTicketDto.builder()                    .ticketId("DB-TK" + t.getId())                    .status(t.getStatus() != null ? t.getStatus().name() : "UNKNOWN")                    .issueType(t.getIssueType() != null ? t.getIssueType().name() : "UNKNOWN")                    .assignedTeam(assignedNames)                    .priority(t.getPriority() != null ? t.getPriority().name() : "Normal")                    .timeUsedMinutes(t.getSpentMinutes() != null ? t.getSpentMinutes() : 0)                    .build();        });    }    // 👈 [Dynamic Status] - လုံးဝ မှန်ကန်ပါသည်    private ProductStatus getDynamicStatus(ClientProduct cp) {        Instant now = Instant.now();        if (cp.getPlanStartDate() != null && cp.getPlanStartDate().isAfter(now)) {            return ProductStatus.UPCOMING;        }        if (cp.getPlanEndDate() != null && cp.getPlanEndDate().isBefore(now)) {            return ProductStatus.EXPIRED;        }        if (cp.getPlanEndDate() != null) {            long daysRemaining = java.time.temporal.ChronoUnit.DAYS.between(now, cp.getPlanEndDate());            if (daysRemaining <= 7) {                return ProductStatus.EXPIRING_SOON;            }        }        return ProductStatus.ACTIVE;    }    // 👈 [mapToResponse] - လုံးဝ မှန်ကန်ပါသည်    private ClientProductResponse mapToResponse(ClientProduct cp) {        return ClientProductResponse.builder()                .id(cp.getId())                .productName(cp.getProduct().getName())                .productDescription(cp.getProduct().getDescription())                .productType(cp.getProduct().getProductType())                .imageUrl(cp.getProduct().getImageUrl())                // 💡 [ပြောင်းလဲချက်] cp.getSupportPlan() အစား cp.getProductPlan().getPlanName() ကို အသုံးပြုထားပါသည်                .supportPlan(cp.getProductPlan().getPlanName())                .purchasedDate(cp.getPurchasedDate())                .planEndDate(cp.getPlanEndDate())                .availableMinutes(cp.getAvailableMinutes())                .totalMinutes(cp.getTotalMinutes())                .status(getDynamicStatus(cp).name())                .build();    }}